def generate_pattern(input_grid):
    rows, cols = len(input_grid), len(input_grid[0])
    fours = set((r, c) for r in range(rows) for c in range(cols) if input_grid[r][c] == 4)

    output = [[0] * cols for _ in range(rows)]

    for r, c in fours:
        # Up: row-1, columns c-2 and c+2
        if r - 1 >= 0:
            for dc in [-2, 2]:
                nc = c + dc
                if 0 <= nc < cols:
                    output[r-1][nc] = 4

        # Same row: columns c-1 and c+1
        for dc in [-1, 1]:
            nc = c + dc
            if 0 <= nc < cols:
                output[r][nc] = 4

        # Down: row+1, column c
        if r + 1 < rows:
            output[r+1][c] = 4

    # Preserve the bar
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 2:
                output[r][c] = 2

    return output

